import pandas as pd
import matplotlib.pyplot as plt
from mpl_toolkits.mplot3d import Axes3D

# 1. Upload data from CSV file generated by the C++ simulator
try:
    data = pd.read_csv('build/simulation_data.csv')
except FileNotFoundError:
    print("Error: file simulation_data.csv not found. Run the C++ simulator first!")
    exit()

fig = plt.figure(figsize=(12, 9))
ax = fig.add_subplot(111, projection='3d')

# 2. Annotation parameter: how often to label the steps (e.g., every 20 steps)
label_every_n = 20

# 3. Draw the trajectories and add timestamps
for part_id in data['id'].unique():
    subset = data[data['id'] == part_id]
    
    # Draw the trajectory line
    line, = ax.plot(subset['x'], subset['y'], subset['z'], label=f'Particle {part_id}', alpha=0.7)
    color = line.get_color() # Get the color of the line for the numbers

    # Add the step numbers
    # We use the modulo % to write only every N rows
    for i, row in subset.iterrows():
        if row['step'] % label_every_n == 0:
            ax.text(row['x'], row['y'], row['z'], 
                    str(int(row['step'])), 
                    color=color, 
                    fontsize=8,
                    fontweight='bold')

# 4. Esthetic of the plot
ax.set_xlabel('X')
ax.set_ylabel('Y')
ax.set_zlabel('Z')
ax.set_title(f'N-Body Trajectories (Labels every {label_every_n} steps)')
ax.legend(loc='upper left', bbox_to_anchor=(1.05, 1))

plt.tight_layout()
plt.show()